// Normaliza el shape del evento de EvoAPI para que las ramas downstream
// puedan asumir un formato común.
//
// EvoAPI v2 emite con shape:
//   { event: 'GROUP_PARTICIPANTS_UPDATE' | 'group.participants.update' | 'MESSAGES_UPSERT' | 'messages.upsert' | ...,
//     instance, data: {...} }
//
// Output:
//   { event_kind: 'group_participants_update' | 'messages_upsert' | 'other',
//     raw: <body completo>, data: <body.data>, instance, event_at }

const body = $input.first().json.body || $input.first().json;
const raw_event = String(body.event || '').toLowerCase().replace(/[.-]/g, '_');
let event_kind = 'other';
if (raw_event === 'group_participants_update') event_kind = 'group_participants_update';
else if (raw_event === 'messages_upsert') event_kind = 'messages_upsert';

return [{
  json: {
    event_kind,
    raw_event,
    data: body.data || {},
    instance: body.instance || null,
    event_at: new Date().toISOString(),
  }
}];

