// Rama join — lógica existente conservada.
// Si la URL anterior fue 'skip' (action != add), o no hay row, devolvemos 0.

const items = $input.all();
if (items.length === 0) return [];
const row = items[0]?.json;
if (!row || !row.id) return [];

const ev = $('Classify event').first().json;
const d = ev.data || {};
const joinedPhones = new Set((d.participants || []).map(p => String(p).split('@')[0]).filter(Boolean));
if (joinedPhones.size === 0) return [];

const oldPending = row.pending_participants || [];
const joinedAt = { ...(row.joined_at || {}) };
const nowIso = ev.event_at;
for (const phone of joinedPhones) {
  if (!joinedAt[phone]) joinedAt[phone] = nowIso;
}

const newPending = oldPending.filter(p => !joinedPhones.has(p.phone));
const allJoinedNow = newPending.length === 0;

return [{
  json: {
    row_id: row.id,
    group_jid: row.group_jid,
    update_pending: newPending,
    update_joined_at: joinedAt,
    all_joined_now: allJoinedNow,
    messages: row.messages || [],
  }
}];

const d = $('GPU: Decide next state').first().json;
const messages = d.messages || [];
const groupJid = d.group_jid;
return messages.map((text, i) => ({ json: { number: groupJid, text, idx: i + 1 } }));

// Rama MESSAGES_UPSERT - extrae datos relevantes del mensaje y filtra.
// Solo nos interesan mensajes de GRUPO (@g.us) con contenido textual.

const ev = $('Classify event').first().json;
const d = ev.data || {};
const key = d.key || {};
const msg = d.message || {};

const remoteJid = key.remoteJid || '';
if (!remoteJid.endsWith('@g.us')) return []; // solo grupos

// Extraer texto del mensaje (varios shapes posibles)
const text = msg.conversation
  || msg.extendedTextMessage?.text
  || msg.imageMessage?.caption
  || msg.videoMessage?.caption
  || null;
if (!text) return []; // ignoramos media sin caption, stickers, etc.

const fromMe = !!key.fromMe;
// participantAlt suele tener el phone canónico con sufijo, key.participant tiene el @lid (id WhatsApp interno)
const participantPhone = String(key.participantAlt || '').split('@')[0] || null;
const pushName = d.pushName || '';
const messageId = key.id || null;
const tsRaw = d.messageTimestamp || 0;
// EvoAPI manda timestamp en segundos
const tsMs = (typeof tsRaw === 'number' ? tsRaw : Number(tsRaw)) * 1000;
const tsIso = tsMs > 0 ? new Date(tsMs).toISOString() : new Date().toISOString();

return [{
  json: {
    group_jid: remoteJid,
    from_me: fromMe,
    participant_phone: participantPhone,
    push_name: pushName,
    text,
    message_id: messageId,
    timestamp_iso: tsIso,
  }
}];

// Combina row + parsed message + resuelve sender role.
// HTTP Request auto-splittea la respuesta array de PostgREST.

const items = $input.all();
if (items.length === 0) return []; // no row → no es nuestro grupo
const row = items[0]?.json;
if (!row || !row.id || !row.hubspot_lead_id) return [];

const m = $('MU: Parse message').first().json;
const expected = row.expected_participants || [];

// Determinar sender
let senderRole = 'unknown';
let senderName = m.push_name || 'desconocido';
if (m.from_me) {
  senderRole = 'setter';
  senderName = 'SDR';
} else if (m.participant_phone) {
  const match = expected.find(p => p.phone === m.participant_phone);
  if (match) {
    senderRole = match.role;
    senderName = match.name;
  }
}

// Format de la línea para el body de la Note
// '[DD/MM HH:MM] Sender (role): texto'
const dt = new Date(m.timestamp_iso);
const fmt = new Intl.DateTimeFormat('es-ES', {
  timeZone: 'Europe/Madrid',
  day: '2-digit', month: '2-digit',
  hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
}).formatToParts(dt).reduce((acc, p) => { acc[p.type] = p.value; return acc; }, {});
const stamp = `${fmt.day}/${fmt.month} ${fmt.hour}:${fmt.minute}`;
const line = `[${stamp}] ${senderName} (${senderRole}): ${m.text}`;

return [{
  json: {
    row_id: row.id,
    hubspot_lead_id: row.hubspot_lead_id,
    hubspot_note_id: row.hubspot_note_id, // puede ser null si es el primer mensaje
    group_subject: row.group_subject,
    sender_name: senderName,
    sender_role: senderRole,
    text: m.text,
    timestamp_iso: m.timestamp_iso,
    line,
  }
}];
